//โค้ดดึง อำเภอ/ตำบล เป็น Select
//ดึงตำบลและรหัสไปรษณีย์มาแสดงเมื่อเลือกอำเภอ
frappe.ui.form.on('polysomnogram', {
    refresh: function(frm) {
        // ตรวจสอบว่ามีการเลือกจังหวัดหรือไม่
        if (frm.doc.province) {
            // ดึงข้อมูลอำเภอเมื่อมีการเลือกจังหวัด
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Amphoe",
                    filters: {
                        province_th: frm.doc.province
                    },
                    fields: ["amphoe_th"],
                    limit_page_length: 100
                },
                callback: function(r) {
                    if (r.message) {
                        let amphoe_options = r.message.map(d => d.amphoe_th);
                        // อัปเดตตัวเลือกในช่องอำเภอ
                        frm.set_df_property('amphoe', 'options', amphoe_options.join('\n'));
                        frm.refresh_field('amphoe');
                    }
                }
            });
        }
        // ตรวจสอบว่ามีการเลือกจังหวัดและอำเภอหรือไม่
        if (frm.doc.province && frm.doc.amphoe) {
            // ดึงข้อมูลตำบลเมื่อมีการเลือกอำเภอ
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Tambon",
                    filters: {
                        province_th: frm.doc.province,
                        amphoe_th: frm.doc.amphoe
                    },
                    fields: ["tambon_th"],
                    limit_page_length: 100
                },
                callback: function(r) {
                    if (r.message) {
                        let tambon_options = r.message.map(d => d.tambon_th);
                        // อัปเดตตัวเลือกในช่องตำบล
                        frm.set_df_property('tambon', 'options', tambon_options.join('\n'));
                        frm.refresh_field('tambon');
                    }
                }
            });
        }
    },
    province: function(frm) {
        if (frm.doc.province) {
            // ดึงข้อมูลอำเภอเมื่อมีการเลือกจังหวัด
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Amphoe",
                    filters: {
                        province_th: frm.doc.province
                    },
                    fields: ["amphoe_th"],
                    limit_page_length: 100
                },
                callback: function(r) {
                    if (r.message) {
                        let amphoe_options = r.message.map(d => d.amphoe_th);
                        // อัปเดตตัวเลือกในช่องอำเภอ
                        frm.set_df_property('amphoe', 'options', amphoe_options.join('\n'));
                        frm.refresh_field('amphoe');
                    }
                }
            });
        } else {
            // ล้างค่าช่อง amphoe, tambon และ postal_code เมื่อ province เป็นค่าว่าง
            frm.set_value('amphoe', "");
            frm.set_value('tambon', "");
            frm.set_value('postal_code', "");
        
        }
    },
    amphoe: function(frm) {
        if (frm.doc.province && frm.doc.amphoe) {
            // ดึงข้อมูลตำบลเมื่อมีการเลือกอำเภอ
            frappe.call({
                method: "frappe.client.get_list",
                args: {
                    doctype: "Tambon",
                    filters: {
                        province_th: frm.doc.province,
                        amphoe_th: frm.doc.amphoe
                    },
                    fields: ["tambon_th"],
                    limit_page_length: 100
                },
                callback: function(r) {
                    if (r.message) {
                        let tambon_options = r.message.map(d => d.tambon_th);
                        // อัปเดตตัวเลือกในช่องตำบล
                        frm.set_df_property('tambon', 'options', tambon_options.join('\n'));
                        frm.refresh_field('tambon');
                    }
                }
            });
        }  else {
            // ล้างค่าช่อง tambon และ postal_code เมื่อ amphoe เป็นค่าว่าง
            frm.set_value('tambon', "");
            frm.set_value('postal_code', "");
        }
    },
    tambon: function(frm) {
        if (frm.doc.province && frm.doc.amphoe && frm.doc.tambon) {
            // ดึงข้อมูลรหัสไปรษณีย์เมื่อมีการเลือกตำบล
            frappe.call({
                method: "frappe.client.get_value",
                args: {
                    doctype: "Tambon",
                    filters: {
                        province_th: frm.doc.province,
                        amphoe_th: frm.doc.amphoe,
                        tambon_th: frm.doc.tambon
                    },
                    fieldname: ["postal_code"],
                    limit_page_length: 100
                },
                callback: function(r) {
                    if (r.message) {
                        frm.set_value('postal_code', r.message.postal_code);
                    }
                }
            });
        }  else {
            // ล้างค่าช่อง tambon และ postal_code เมื่อ amphoe เป็นค่าว่าง
            frm.set_value('postal_code', "");
        }
    }
});

frappe.ui.form.on('polysomnogram', {
    weight: function(frm) {
        calculate_bmi(frm);
    },
    height: function(frm) {
        calculate_bmi(frm);
    }
});

function calculate_bmi(frm) {
    if (frm.doc.weight && frm.doc.height) {
        let height_m = frm.doc.height / 100; // แปลง cm เป็น m
        let bmi = frm.doc.weight / (height_m * height_m);
        frm.set_value('bmi', bmi.toFixed(2)); // ปัดค่า BMI ให้เหลือ 2 ตำแหน่ง
        
        // กำหนดผลลัพธ์ตามเกณฑ์ WHO
        let result = "";
        if (bmi < 18.5) {
            result = "Underweight (น้ำหนักต่ำกว่าเกณฑ์)";
        } else if (bmi >= 18.5 && bmi < 25) {
            result = "Normal weight (น้ำหนักปกติ)";
        } else if (bmi >= 25 && bmi < 30) {
            result = "Overweight (น้ำหนักเกิน)";
        } else {
            result = "Obese (โรคอ้วน)";
        }

        frm.set_value('result_bmi', result); // อัปเดตผลลัพธ์ BMI
    } else {
        frm.set_value('bmi', ""); // รีเซ็ตค่า BMI ถ้าไม่มีข้อมูล
        frm.set_value('result_bmi', ""); // รีเซ็ตค่า Result BMI ถ้าไม่มีข้อมูล
    }
}

//รวมค่าการง่วงนอน
frappe.ui.form.on('polysomnogram', {
    refresh: function(frm) {
        // ตั้ง flag เพื่อบอกว่า ตอนนี้เป็นการโหลดฟอร์ม ไม่ต้องคำนวณ
        frm._loading = true;

        // รอให้ field โหลดครบก่อน แล้วค่อยเคลียร์ flag
        frappe.after_ajax(() => {
            frm._loading = false;
            // ไม่ต้องคำนวณตอน refresh เพราะอาจ trigger not saved
        });
    }
});

// ผูก event กับ select_key0 - select_key7
['select_key0', 'select_key1', 'select_key2', 'select_key3',
 'select_key4', 'select_key5', 'select_key6', 'select_key7'].forEach(field => {
    frappe.ui.form.on('polysomnogram', {
        [field]: function(frm) {
            if (!frm._loading) {
                calculate_total_and_evaluation(frm);
            }
        }
    });
});

function calculate_total_and_evaluation(frm) {
    let total = 0;
    let all_fields_filled = true;

    for (let i = 0; i <= 7; i++) {
        let field_name = `select_key${i}`;
        let value = frm.doc[field_name];

        if (value === undefined || value === null || value === "") {
            all_fields_filled = false;
            break;
        }

        let parsed = parseInt(value);
        if (isNaN(parsed)) {
            all_fields_filled = false;
            break;
        }

        total += parsed;
    }

    if (all_fields_filled) {
        let new_evaluation = "";
        if (total >= 16) {
            new_evaluation = "มีอาการง่วงนอนอันตรายมาก ควรเข้ารับการตรวจอย่างเร่งด่วน";
        } else if (total >= 9) {
            new_evaluation = "มีอาการง่วงนอนมาก ควรเข้ารับการตรวจอย่างเร่งด่วน";
        } else if (total >= 5) {
            new_evaluation = "มีแนวโน้มของความผิดปกติ ควรเข้ารับการตรวจ";
        } else {
            new_evaluation = "อยู่ในเกณฑ์ปกติ";
        }

        // set_value เฉพาะเมื่อค่าจริง ๆ เปลี่ยน
        if (frm.doc.total !== total) {
            frm.set_value('total', total);
        }

        if (frm.doc.evaluation !== new_evaluation) {
            frm.set_value('evaluation', new_evaluation);
        }
    }
}





