function update_fullname(frm) {
    // ตรวจสอบว่า salutation, fname, และ lastname ทั้งสามมีค่าหรือไม่
    if (frm.doc.salutation && frm.doc.fname && frm.doc.lastname) {
        // คำนวณและตั้งค่า fullname
        frm.set_value('fullname', frm.doc.salutation + ' ' + frm.doc.fname + ' ' + frm.doc.lastname);
    } else {
        // ถ้ายังไม่ครบ ให้ลบค่า fullname
        frm.set_value('fullname', '');
    }

    // ตรวจสอบว่า salutation_r, fname_r, และ lastname_r ทั้งสามมีค่าหรือไม่
    if (frm.doc.salutation_r && frm.doc.fname_r && frm.doc.lastname_r) {
        // คำนวณและตั้งค่า fullname_r
        frm.set_value('fullname_r', frm.doc.salutation_r + ' ' + frm.doc.fname_r + ' ' + frm.doc.lastname_r);
    } else {
        // ถ้ายังไม่ครบ ให้ลบค่า fullname_r
        frm.set_value('fullname_r', '');
    }

    // ตรวจสอบว่า salutation_eng, fname_eng, และ lastname_eng ทั้งสามมีค่าหรือไม่
    if (frm.doc.salutation_eng && frm.doc.fname_eng && frm.doc.lastname_eng) {
        // คำนวณและตั้งค่า fullname_r
        frm.set_value('fullname_eng', frm.doc.salutation_eng + ' ' + frm.doc.fname_eng + ' ' + frm.doc.lastname_eng);
   } else {
        // ถ้ายังไม่ครบ ให้ลบค่า fullname_r
        frm.set_value('fullname_eng', '');
    }

    // รีเฟรชค่าในฟอร์มให้แสดงผลถูกต้อง
    frm.refresh_field('fullname');
    frm.refresh_field('fullname_r');
    frm.refresh_field('fullname_eng');
}


//checkbox
frappe.ui.form.on('polysomnogram', {
    refresh: function(frm) {
        // Set up event handlers for all checkboxes on page load
        //console.log("polysomnogram form loaded");
    },
    
    // กำหนดคู่ checkbox ในรูปแบบ mapping
    // format: 'key': 'opposite_key'
    setup: function(frm) {
        // กำหนดคู่ของ checkbox แบบ mapping 
        frm.checkbox_pairs = {
            'have': 'null',
            'coffee': 'nocoffee',
            'drink': 'nodrink',
            'cigarette': 'nocigarette',
            'snore': 'nosnore',
            'sleeptest': 'non',
            'cpap': 'nocpap',
            'drug': 'no_drug'
            // เพิ่มคู่ใหม่ตรงนี้ เช่น 'new_field': 'opposite_new_field'
        };
        
        // สร้าง event handlers สำหรับทุกคู่ checkbox โดยอัตโนมัติ
        Object.keys(frm.checkbox_pairs).forEach(function(field) {
            const opposite = frm.checkbox_pairs[field];
            
            // สร้าง handler สำหรับ field หลัก
            frappe.ui.form.on('polysomnogram', field, function(frm) {
                if(frm.doc[field] == 1) {
                    frm.set_value(opposite, 0);
                    frm.refresh_field(opposite);
                }
            });
            
            // สร้าง handler สำหรับ field ตรงข้าม
            frappe.ui.form.on('polysomnogram', opposite, function(frm) {
                if(frm.doc[opposite] == 1) {
                    frm.set_value(field, 0);
                    frm.refresh_field(field);
                }
            });
        });
    },
    
    validate: function(frm) {
        // ตรวจสอบทุกคู่ checkbox
        Object.keys(frm.checkbox_pairs).forEach(function(field) {
            const opposite = frm.checkbox_pairs[field];
            
            if(frm.doc[field] == 1 && frm.doc[opposite] == 1) {
                // ถ้าทั้งสองช่องถูกติ๊ก ให้ใช้ค่าล่าสุดที่เปลี่ยน
                let field_changed = frm.get_last_changed_field();
                if(field_changed === field) {
                    frm.set_value(opposite, 0);
                } else if(field_changed === opposite) {
                    frm.set_value(field, 0);
                }
            }
        });
    }
});


