frappe.ui.form.on('polysomnogram', {
    setup: function(frm) {
        // กำหนด checkbox ทั้งหมดที่เกี่ยวข้อง
        frm.fip_checkboxes = ['chk_imga', 'chk_imgb', 'chk_imgc', 'chk_imgd', 'chk_imge'];

        // วน loop เพื่อตั้ง event handler ให้ทุก checkbox
        frm.fip_checkboxes.forEach(function(field) {
            frappe.ui.form.on('polysomnogram', field, function(frm) {
                if (frm.doc[field]) { // ถ้าติ๊ก checkbox นี้
                    frm.fip_checkboxes.forEach(function(other_field) {
                        if (other_field !== field) {
                            frm.set_value(other_field, 0); // เอา checkbox อื่นออก
                        }
                    });
                }
            });
        });
    }
});

frappe.ui.form.on('polysomnogram', {
    birthday: function(frm) {
        if (frm.doc.birthday) {
            let birthDate = new Date(frm.doc.birthday);
            let today = new Date();
            
            let age = today.getFullYear() - birthDate.getFullYear();
            let monthDiff = today.getMonth() - birthDate.getMonth();
            let dayDiff = today.getDate() - birthDate.getDate();

            // ปรับอายุถ้าปีนี้ยังไม่ถึงวันเกิด
            if (monthDiff < 0 || (monthDiff === 0 && dayDiff < 0)) {
                age--;
            }

            frm.set_value('age', age);
        }
    }
});


// ดึงชื่อจาก User ที่ login อยู่
frappe.ui.form.on('polysomnogram', {
    onload: function(frm) {
        if (frm.is_new()) {
            // รับอีเมลของผู้ใช้ปัจจุบัน
            let user_email = frappe.session.user;

            // เรียกใช้ฟังก์ชันฝั่งเซิร์ฟเวอร์เพื่อรับข้อมูลผู้ใช้
            frappe.call({
                method: 'frappe.client.get',
                args: {
                    doctype: 'User',
                    name: user_email
                },
                callback: function(response) {
                    if (response.message) {
                        let user_doc = response.message;
                        // เข้าถึงฟิลด์ full_name
                        let full_name = user_doc.full_name;
                        
                        // ตั้งค่าในแบบฟอร์มกำหนดการทำงาน
                        frm.set_value('fullname_emp', full_name);
                        
                        // รีเฟรชฟิลด์เพื่อให้แน่ใจว่ามีการอัปเดตแล้ว
                        frm.refresh_field('fullname_emp');
                       
                    }
                }
            });
        }
    }
});

