frappe.ui.form.on('polysomnogram', {
    after_save: function(frm) {
        let action = null;

        if (frm.doc.wf_poly_state === "เข้ารับบริการแล้ว อยู่ระหว่างรอฟังผลตรวจ") {
            action = "บันทึก";

        } else if (frm.doc.is_sleeptest === "สนใจเข้ารับบริการ" && frm.doc.sleeptest_date) {
            action = "นัดหมาย";

        // ปกติสนใจเข้ารับบริการ (ไม่มีวัน)
        } else if (frm.doc.is_sleeptest === "สนใจเข้ารับบริการ") {
            action = "สนใจเข้ารับบริการ";

        } else if (frm.doc.is_sleeptest === "รอตัดสินใจ") {
            action = "รอตัดสินใจ";

        } else if (frm.doc.is_sleeptest === "ปฏิเสธเข้ารับบริการ") {
            action = "ปฏิเสธเข้ารับบริการ";

        }
        
        if (action) {
            frappe.call({
                method: "frappe.model.workflow.apply_workflow",
                args: {
                    doc: frm.doc,
                    action: action
                },
                callback: function() {
                    frm.reload_doc();  // โหลดเอกสารใหม่เพื่ออัปเดตสถานะ
                }
            });
        }
    }
});

