                            let day = ('0' + date.getDate()).slice(-2);  // ให้วันที่แสดงเป็น 2 หลัก
                            let month = ('0' + (date.getMonth() + 1)).slice(-2);  // ให้เดือนแสดงเป็น 2 หลัก
                            let year = date.getFullYear();  // ปีที่แสดง 4 หลัก
