                    function isTodayAfterSleepDatePlus11(dateString) {
                        if (!dateString) return false;

                        let baseDate = new Date(dateString);
                        baseDate.setDate(baseDate.getDate() + 11);  // +1 และ +10 วันในครั้งเดียว

                        let today = new Date();
                        return baseDate.toDateString() === today.toDateString();
