        // เรียกฟังก์ชัน fetchData เพื่อดึงข้อมูลและคำนวณแจ้งเตือนตั้งแต่เริ่มต้น
        fetchData();
        fetchAppointment();
        fetchCompleted();

        // ติดตั้งฟังก์ชันที่จะทำงานเมื่อมีการสร้างหรืออัปเดตเอกสารใหม่
        frappe.realtime.on('new_polysomnogram_created', function(data) {
            // ตรวจสอบว่าเอกสารใหม่มีสถานะ "เข้ารับบริการแล้ว อยู่ระหว่างรอฟังผลตรวจ"
            if (data.wf_poly_state === 'เข้ารับบริการแล้ว อยู่ระหว่างรอฟังผลตรวจ' || data.wf_poly_state === 'นัดหมายวันเข้ารับบริการ' ) {
                fetchData();  // รีเฟรชข้อมูลการแจ้งเตือน
                fetchAppointment();
                fetchCompleted();
            }
        });

        // ติดตั้งฟังก์ชันที่จะทำงานเมื่อสถานะ wf_poly_state เปลี่ยน
        frappe.realtime.on('polysomnogram_update', function(data) {
            // ตรวจสอบการเปลี่ยนแปลงสถานะ
            if (data.wf_poly_state === 'เข้ารับบริการแล้ว อยู่ระหว่างรอฟังผลตรวจ' || data.wf_poly_state === 'นัดหมายวันเข้ารับบริการ') {
                fetchData();  // รีเฟรชข้อมูลการแจ้งเตือน
                fetchAppointment();
                fetchCompleted();
            } else {
                fetchData();  // รีเฟรชข้อมูลการแจ้งเตือน
                fetchAppointment();
                fetchCompleted();
            }
        });
    }
};
